import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";

export default function Login() {
  const navigate = useNavigate();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const handleLogin = (e) => {
    e.preventDefault();

    const user = JSON.parse(localStorage.getItem("user"));

    if (
      user &&
      user.email === email &&
      user.password === password
    ) {
      alert("Login Successful");

      navigate("/dashboard");
    } else {
      alert("Invalid Email or Password");
    }
  };

  return (
    <div
      style={{
        height: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        background: "#747a7c",
      }}
    >
      <form
        onSubmit={handleLogin}
        style={{
          background: "Black",
          padding: "30px",
          borderRadius: "15px",
          width: "350px",
        }}
      >
        <h1>PlaceMux Login</h1>

        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          style={{
            width: "100%",
            padding: "12px",
            marginBottom: "15px",
          }}
        />

        <input
          type="password"
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          style={{
            width: "100%",
            padding: "12px",
            marginBottom: "15px",
          }}
        />

        <button
          type="submit"
          style={{
            width: "100%",
            padding: "12px",
            background: "#21ce3e",
            color: "white",
            border: "none",
            borderRadius: "8px",
          }}
        >
          Login
        </button>

        <p style={{ marginTop: "15px" }}>
          New User? <Link to="/register">Register</Link>
        </p>
      </form>
    </div>
  );
}
